items.sort((a, b) => a.json.idx - b.json.idx);

const cfg = $('Config').first().json._cfg;
const headers = {
  apikey: cfg.supabase_key,
  Authorization: 'Bearer ' + cfg.supabase_key
};

const parts = [];
