    encoding: 'arraybuffer'
  });
  const ext = it.json.fetch_url.split('?')[0].split('.').pop().toLowerCase();
  const mime = ({ png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' })[ext] || 'image/jpeg';
