const asm  = $('Assemble row').first().json;
const base = $('Config').first().json._cfg.supabase_url;
return [{ json: {
  generation_id:        row?.id || asm.generation_id,
  user_id:              asm.user_id,
  session_id:           asm.session_id,
  kind:                 asm.kind,
  parent_generation_id: asm.parent_generation_id,
  model_id:             asm.model_id,
  latency_ms:           asm.latency_ms,
  cost_usd:             asm.cost_usd || 0,
  room_type:            asm.room_type,
  style_tag:            asm.style_tag,
  output_url:           base + '/storage/v1/object/public/' + asm.output_image_path,
  created_at:           row?.created_at || new Date().toISOString()
